package it.randyflow.service;
import it.randyflow.dto.ApiDtos.StatsDto; import it.randyflow.repository.*; import it.randyflow.security.UserContext; import java.time.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class StatsService { private final ApplicationRepository data;private final ExamRepository exams;private final UserContext users;public StatsService(ApplicationRepository data,ExamRepository exams,UserContext users){this.data=data;this.exams=exams;this.users=users;}public StatsDto get(){var ids=exams.findByOwnerIdOrderByCreatedAtDesc(users.idOrLegacy()).stream().map(e->e.id).toList();LocalDate start=LocalDate.now().minusDays(6);int minutes=data.minutesSince(start,ids);var logs=data.logs(ids).stream().filter(l->!l.logDate.isBefore(start)).toList();int slides=logs.stream().mapToInt(l->Math.max(0,l.toPage-l.fromPage+1)).sum();long attempts=data.quizAttempts(ids);int accuracy=attempts==0?0:(int)Math.round(100d*data.correctQuizAttempts(ids)/attempts);List<Map<String,Object>> daily=new ArrayList<>();for(int i=0;i<7;i++){LocalDate day=start.plusDays(i);int studied=logs.stream().filter(l->l.logDate.equals(day)).mapToInt(l->l.minutes).sum();daily.add(Map.of("date",day.toString(),"plannedMin",0,"studiedMin",studied,"slides",logs.stream().filter(l->l.logDate.equals(day)).mapToInt(l->Math.max(0,l.toPage-l.fromPage+1)).sum()));}return new StatsDto(minutes,slides,0,accuracy,0,daily,List.of(),List.of());}}
